
import type { ReturnActor } from './ReturnActor.js';

export type ReturnInspectionLineItem = { /** RFC3339 timestamp. Format: date-time. */ "acceptance_decided_at"?: string; "acceptance_decided_by"?: ReturnActor; "acceptance_decision_reason"?: "inspection_result" | "return_policy" | "manual_review" | "other" | (string & {}); "acceptance_decision_reason_message"?: string; "acceptance_status": "accepted" | "rejected" | "review_required" | (string & {}); /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "available_disposition_quantity": string; /** `undetermined`: The item's condition could not be assessed. */ "condition": "new" | "unopened" | "opened" | "used" | "damaged" | "defective" | "incomplete" | "undetermined" | (string & {}); "finding_codes": Array<"matches_expected_item" | "wrong_item" | "damaged" | "defective" | "used" | "missing_parts" | "empty_package" | "counterfeit_suspected" | "other" | (string & {})>; "internal_note"?: string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "quantity": string; "return_inspection_id": string; "return_inspection_line_item_id": string; "return_line_item_id"?: string; "return_receipt_line_item_id": string; "supported_actions": Array<string>; };
